#!/usr/bin/env bash
# Launcher of option B (docs/plans/2026-11-08-hl11-small-plan.md, section 7) after `route`: tier runs with the JRC 2000 W0
# in 10 processes, retry, 45 km edge pass, lock, widening (10 processes) and its lock, tier summary, floors, coverage.
# DO NOT EDIT THIS FILE WHILE IT IS RUNNING. Usage: bash 04_Code/scripts/hl11_b_batch.sh
cd "$(dirname "$0")/../.." || exit 1
LOG=05_Results/by_date/2026-11-08/hl11_small_v1/b/logs; mkdir -p "$LOG"
export PYTHONIOENCODING=utf-8 OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
run() { .venv/Scripts/python.exe -I 04_Code/scripts/hl11_small_b_v1.py "$@" 2>&1 | grep --line-buffered -v "^r2 {" | grep --line-buffered -v "/C {'iteration'"; }
N=10
for i in $(seq 1 $N); do run run --part "$i/$N" >> "$LOG/run_${i}of${N}.log" & done; wait
run run >> "$LOG/retry.log"
run retry-edge >> "$LOG/edge.log"
run lock >> "$LOG/lock.log"
for i in $(seq 1 $N); do run widen --part "$i/$N" >> "$LOG/widen_${i}of${N}.log" & done; wait
run widen >> "$LOG/widen_retry.log"
run widen-lock >> "$LOG/widen_lock.log"
run tier-summary >> "$LOG/tier_summary.log"
run floor >> "$LOG/floor.log"
run coverage >> "$LOG/coverage.log"
echo "batch finished $(date -Iseconds)" >> "$LOG/batch.log"
